<?php
use Drupal\lit_map\Service\CommunityPlaces;
$v=\Drupal::service('lit_contribution.validator');$towns=$v->references()['municipalities'];$raw=json_decode(file_get_contents(dirname(DRUPAL_ROOT).'/fixtures/lit-export/questionnaire-v2.json'),TRUE)['submissions'][0];
$raw['answers']['resolutions']=[];
$db=\Drupal::database();$snapshot=fn()=>hash('sha256',json_encode([$db->select('lit_contribution_review','r')->fields('r')->orderBy('id')->execute()->fetchAll(),$db->select('lit_contribution_publication','p')->fields('p')->execute()->fetchAll(),\Drupal::service('lit_contribution.publication')->publicData()]));$before=$snapshot();$n=0;$ok=function($x,$m)use(&$n){if(!$x)throw new RuntimeException($m);$n++;};
foreach(['Whippany','Cedar Knolls','Hanover Township','Hanover'] as $place){$s=$raw;$s['answers']['questions']['q01']='no';$s['answers']['questions']['q02']=$place.', NJ';$s['answers']['questions']['q03']='Morris';$a=$v->normalize($s,FALSE)['answers'];$ok($a['municipality']==='m3402729550' && $a['county_geoid']==='34027' && !$a['flags'],'Parent normalization '.$place);$ok($a['questions']['q02']===$place.', NJ','Private original retained');}
$ok(CommunityPlaces::candidates('East Hanover Township','34027','NJ',$towns)===['m3402719210'],'East Hanover stays distinct');
$ok(CommunityPlaces::candidates('Whippany','34013','NJ',$towns)===[],'Wrong county cannot match');$ok(CommunityPlaces::candidates('Whippany','34027','NY',$towns)===[],'Wrong state cannot match');
$s=$raw;$s['answers']['questions']['q01']='no';$s['answers']['questions']['q02']='Whippany, NY';$s['answers']['questions']['q03']='Morris';$a=$v->normalize($s,FALSE)['answers'];$ok($a['municipality']===NULL && in_array('Non-NJ residence',$a['flags']),'Non NJ requires review');
$aliases=CommunityPlaces::load($towns);$aliases[]=['name'=>'Whippany','state'=>'NJ','county'=>'34027','municipality'=>'m3402719210'];$ok(count(CommunityPlaces::candidates('Whippany','34027','NJ',$towns,$aliases))===2,'Ambiguity returns candidates, not arbitrary winner');
$public=\Drupal::service('lit_contribution.publication')->publicData()['survey'];$ok(count(array_filter($public['municipalities'],fn($t)=>$t['id']==='m3402729550'))===1,'Parent remains single municipality');$ok($snapshot()===$before,'Review, publication and every total unchanged');
echo "$n community lookup/privacy/preservation checks passed.\n";echo json_encode(['Hanover_published_counts'=>$public['breakdown']['34027']['m3402729550']??NULL,'East_Hanover_published_counts'=>$public['breakdown']['34027']['m3402719210']??NULL])."\n";
